namespace RDMSharpTests.Metadata.Parser;

/// <summary>
/// Faulty Payloads of real devices, captured with Wireshark. Generated by tools/RdmDumpTests/faulty_gen.py.
/// </summary>
public partial class TestFaultyDevicePayloads
{
    private static IEnumerable<FaultyPayload> getDumpPayloads()
    {
        // GenVI Dimmer v1.08.pcapng, frame 812
        yield return new FaultyPayload(ERDM_Command.GET_COMMAND_RESPONSE, ERDM_Parameter.CURVE, 0x4C73,
            new byte[] { 0x03 },
            "PDL 1, the define needs 2");
        // DZP Esprit Creos.pcapng, frame 1837
        yield return new FaultyPayload(ERDM_Command.GET_COMMAND_RESPONSE, ERDM_Parameter.DMX_PERSONALITY, 0x5377,
            new byte[] { 0x01 },
            "PDL 1, the define needs 2");
        // JBL P10.pcapng, frame 614
        yield return new FaultyPayload(ERDM_Command.GET_COMMAND_RESPONSE, ERDM_Parameter.FACTORY_DEFAULTS, 0x4A42,
            new byte[] { 0x02 },
            "Boolean status is 0x02, only 0x00 and 0x01 are valid");
        // Martin MAC Aura XIP v1.3.1.pcapng, frame 284
        yield return new FaultyPayload(ERDM_Command.GET_COMMAND_RESPONSE, ERDM_Parameter.IPV4_STATIC_ADDRESS, 0x4D50,
            new byte[] {  },
            "PDL 0, the define needs 9");
        // ACME CM S2 V20.pcapng, frame 88
        yield return new FaultyPayload(ERDM_Command.GET_COMMAND_RESPONSE, ERDM_Parameter.PARAMETER_DESCRIPTION, 0x3806,
            new byte[] { 0xa0, 0x10, 0x01, 0x03, 0x03, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02, 0x00, 0x00, 0x00, 0x01, 0x46, 0x41, 0x4e, 0x5f, 0x4d, 0x4f, 0x44, 0x45, 0x20, 0x30, 0x3a, 0x53, 0x74, 0x61, 0x6e, 0x64, 0x61, 0x72, 0x64, 0x20, 0x31, 0x3a, 0x51, 0x75, 0x69, 0x65, 0x74, 0x20, 0x32, 0x3a, 0x54, 0x68, 0x65 },
            "PDL 53, the define allows at most 52");
        // Martin MAC One v1.3.1 Cleaned.pcapng, frame 297
        yield return new FaultyPayload(ERDM_Command.GET_COMMAND_RESPONSE, ERDM_Parameter.PRESET_PLAYBACK, 0x4D50,
            new byte[] { 0x00, 0x00, 0xff, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 },
            "PDL 9, the define needs 3");
        // Litecraft (LMP) Wash XT v1.0.pcapng, frame 149
        yield return new FaultyPayload(ERDM_Command.GET_COMMAND_RESPONSE, ERDM_Parameter.STATUS_MESSAGES, 0x08E4,
            new byte[] { 0x00 },
            "PDL 1 does not fit the define (slots[0].subdevice_id: 1 of 2 bytes)");
    }
}
